actions.script:
// Lock the existing shop PIN row to serialize the first attempt as well as retries.
def pin = ec.entity.find('moqui.security.UserPreference').condition('userId',access.organizationPartyId)
        .condition('preferenceKey','POS_DISC_PIN').forUpdate(true).one()
if (!pin?.preferenceValue) return
def attempt = ec.entity.find('zenith.erp.pos.PosManagerPinAttempt').condition('organizationPartyId',access.organizationPartyId)
        .condition('userId',ec.user.userId).forUpdate(true).one()
if (attempt?.lockedUntil && attempt.lockedUntil > ec.user.nowTimestamp) return
valid = java.security.MessageDigest.isEqual(pin.preferenceValue.getBytes('UTF-8'),(managerPin ?: '').toString().getBytes('UTF-8'))
def failed = valid ? 0 : ((attempt?.lockedUntil ? 0 : (attempt?.failedAttempts ?: 0)) as int) + 1
def values = [organizationPartyId:access.organizationPartyId,userId:ec.user.userId,failedAttempts:failed,
    lockedUntil:failed >= 5 ? new java.sql.Timestamp(ec.user.nowTimestamp.time + 300000L) : null]
if (attempt) { attempt.setAll(values); attempt.update() }
else ec.entity.makeValue('zenith.erp.pos.PosManagerPinAttempt').setAll(values).create()

def lines = ec.entity.find('zenith.erp.pos.PosTransactionItem').condition('transactionId',transactionId).orderBy('itemSeqId').list()
def free = lines.findAll { ((it.unitPrice ?: 0) as BigDecimal) <= 0 || ((it.lineTotal ?: 0) as BigDecimal) <= 0 }
freeItemCount = free.size()
def decimal = { value -> ((value ?: 0) as BigDecimal).stripTrailingZeros().toPlainString() }
// The row stamp prevents reusing an approval after a free line is changed and restored.
snapshotJson = groovy.json.JsonOutput.toJson(free.collect { line ->
    [seq:line.itemSeqId,product:line.productId,mode:line.salesModeId,quantity:decimal(line.quantity),
     price:decimal(line.unitPrice),discount:decimal(line.discountAmount),total:decimal(line.lineTotal),stamp:line.lastUpdatedStamp?.time]
})
def txn = ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',transactionId).one()
fingerprint = java.security.MessageDigest.getInstance('SHA-256').digest(((txn.sessionId ?: '') + '\n' + snapshotJson).getBytes('UTF-8')).encodeHex().toString()
freeItems = free.collect { [seq:it.itemSeqId,product:it.productId,name:it.productName,quantity:decimal(it.quantity),
    price:decimal(it.unitPrice),discount:decimal(it.discountAmount),total:decimal(it.lineTotal),mode:it.salesModeId] }
// Stable across an amendment's rollback/retry; still bound to the exact displayed contents.
approvalFingerprint = java.security.MessageDigest.getInstance('SHA-256')
        .digest(((txn.sessionId ?: '') + '\n' + groovy.json.JsonOutput.toJson(freeItems)).getBytes('UTF-8')).encodeHex().toString()
def approval = free ? ec.entity.find('zenith.erp.pos.PosFreeItemApproval').condition('organizationPartyId',access.organizationPartyId)
        .condition('transactionId',transactionId).condition('fingerprint',fingerprint).orderBy('-approvalDate').one() : null
approvalId = approval?.approvalId
// Per-org opt-in (default OFF): the approval gate is inert unless the organization
// has PosOrgBillingConfig.freeItemApproval='Y'. No config row => no gate (no-op).
def _billingCfg = ec.entity.find('zenith.erp.pos.PosOrgBillingConfig').condition('organizationPartyId',access.organizationPartyId).one()
required = (_billingCfg?.freeItemApproval == 'Y') && freeItemCount > 0 && !approvalId
